/*##-3- Configure the Eval I2C peripheral #######################################*/
  /* Enable I2C clock */
  EVAL_I2C1_CLK_ENABLE();

/* Force the I2C peripheral clock reset */
  EVAL_I2C1_FORCE_RESET();

/* Release the I2C peripheral clock reset */
  EVAL_I2C1_RELEASE_RESET();
}

