{
    uint32_t index = 0;

if(lcd_drv->DrawVLine != NULL)
    {
        LCD_SetDisplayWindow(Ypos, Xpos, 1, Length);
        lcd_drv->DrawVLine(DrawProp.TextColor, Ypos, Xpos, Length);
        LCD_SetDisplayWindow(0, 0, BSP_LCD_GetXSize(), BSP_LCD_GetYSize());
    }
