  if ((HAL_ADC_RegisterCallback(&hadc, HAL_ADC_MSPINIT_CB_ID, PWR_ADC_MspInit) != HAL_OK)
   || (HAL_ADC_RegisterCallback(&hadc, HAL_ADC_MSPDEINIT_CB_ID, PWR_ADC_MspDeInit) != HAL_OK))
  {
    /* Callback function registration Error */
    error++;
  }

