                                             hadc.Init.Resolution);

/* Start conversion */
  if (HAL_ADC_Stop(&hadc) != HAL_OK)
  {
    error++;
  }

HAL_Delay(100);

/* Start conversion */
  if (HAL_ADC_Start(&hadc) != HAL_OK)
  {
    error++;
  }

/* Wait for conversion completion */
  if (HAL_ADC_PollForConversion(&hadc, 10) != HAL_OK)
  {
    error++;
  }

/* Translate ADC conversion into voltage level */
  *voltageDCDCOnT10 = __HAL_ADC_CALC_DATA_TO_VOLTAGE(VREFANALOG_VOLTAGE,
                                             HAL_ADC_GetValue(&hadc),
                                             hadc.Init.Resolution);

/* Uninit GPIO PIN */
  HAL_GPIO_DeInit(GPIO_PORT[GPIO_V_CTL2], GPIO_PIN[GPIO_V_CTL2]);
  HAL_GPIO_DeInit(GPIO_PORT[GPIO_V_CTL1], GPIO_PIN[GPIO_V_CTL1]);

/* De-initialize ADC& */
  HAL_ADC_DeInit(&hadc);

/* Un-register ADC MSP callback functions */
  if ((HAL_ADC_UnRegisterCallback(&hadc, HAL_ADC_MSPINIT_CB_ID) != HAL_OK)
   || (HAL_ADC_UnRegisterCallback(&hadc, HAL_ADC_MSPDEINIT_CB_ID) != HAL_OK)
   || (HAL_ADC_UnRegisterCallback(&hadc, HAL_ADC_CONVERSION_COMPLETE_CB_ID) != HAL_OK))
  {
    /* MSP callback function registration Error */
    error++;
  }

/* Disable ADC clock */
  DB_ADC_CLK_DISABLE();

/* Reset GPIO configuration */
  HAL_GPIO_DeInit(DB_DETECT_GPIO_PORT, gpio_config.Pin);
}

